def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    H, W = g.shape
    for y in range(H):
        for x in range(W):
            if g[y, x] == bg:
                continue
            if y > 0 and x > 0 and g[y-1, x-1] != bg:
                continue  # not the start of a diagonal line
            i, cy, cx = 0, y, x
            while cy < H and cx < W and g[cy, cx] != bg:
                if i % 2 == 1:
                    out[cy, cx] = 4
                i += 1
                cy += 1
                cx += 1
            emit(out, f"Diagonal line starting at ({y},{x}) with {i} cells: every second cell along it recoloured to 4.")
    emit(out, "All diagonal lines processed; final grid.")
    return out
